-- Preload the 20 Uyo hotel profiles from the 7EVEN onboarding archive.
-- These are directory-only leads, never bookable until the authorised property team claims,
-- verifies the profile, configures room categories/rate plans and publishes nightly inventory.
ALTER TABLE seven.discovery_listings
  ADD COLUMN IF NOT EXISTS claimed_business_id uuid,
  ADD COLUMN IF NOT EXISTS claimed_at timestamptz;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='discovery_listings_claimed_business_fk') THEN
    ALTER TABLE seven.discovery_listings
      ADD CONSTRAINT discovery_listings_claimed_business_fk
      FOREIGN KEY (claimed_business_id) REFERENCES seven.businesses(business_id) ON DELETE SET NULL;
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS discovery_listings_claimed_business_idx
  ON seven.discovery_listings (claimed_business_id)
  WHERE claimed_business_id IS NOT NULL;

